return $input.all().map(item => {
  const data = item.json;

  const cleanText = (text = "") =>
    String(text)
      .replace(/<[^>]*>/g, " ")
      .replace(/&nbsp;/g, " ")
      .replace(/&amp;/g, "&")
      .replace(/&quot;/g, '"')
      .replace(/&#39;|&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/\s+/g, " ")
      .trim();

  return {
    json: {
      title: cleanText(data.title),
      description: cleanText(data.description),
      link: data.link,
      pubDate: data.pubDate
    }
  };
});

