const articles = $input.all();

const formatted = articles.map((item, index) => {
  const a = item.json;

  return `${index + 1}. Title: ${a.title || ""}
Description: ${a.description || ""}
Date: ${a.pubDate || ""}
Source link: ${a.link || ""}`;
});

return [{
  json: {
    articlesText: formatted.join("\n\n")
  }
}];

const text = $input.first().json.emailBody || "";

const escapeHtml = (s) => String(s)
  .replace(/&/g, "&amp;")
  .replace(/</g, "&lt;")
  .replace(/>/g, "&gt;");

const headings = [
  "India News",
  "AI & Technology",
  "Student Opportunities",
  "Science Discoveries",
  "Amazing Fact",
  "English Word"
];

const sections = [];
let current = null;

for (const line of text.split("\n")) {
  const cleaned = line.trim();
  if (!cleaned) continue;

  // Ignore the main email title
  if (/^Your Daily Knowledge Boost$/i.test(cleaned)) continue;

  const heading = headings.find(h =>
    cleaned.replace(/^\d+\.\s*/, "").replace(/:$/, "").trim()
      .toLowerCase() === h.toLowerCase()
  );

  if (heading) {
    current = { heading, body: [] };
    sections.push(current);
  } else if (current) {
    current.body.push(cleaned);
  }
}

let html = `
<div style="font-family:Arial,sans-serif;max-width:650px;margin:auto;color:#dce5e8;line-height:1.7;background:#10131b;padding:16px">
  <div style="background:#174c3c;color:white;padding:24px;border-radius:12px;margin-bottom:24px">
    <h1 style="margin:0 0 12px;font-size:30px">Your Daily Knowledge Boost</h1>
    <p style="margin:0;font-size:17px">Your daily dose of news, discovery and learning.</p>
  </div>
`;

for (const section of sections) {
  const body = section.body.map(line =>
    `<p style="margin:8px 0">${escapeHtml(line.replace(/^-\s*/, ""))}</p>`
  ).join("");

  html += `
  <div style="padding:20px;margin-bottom:16px;border:1px solid #343941;border-radius:12px;background:#10131b">
    <h2 style="color:#75c9ae;margin:0 0 16px;font-size:23px">${escapeHtml(section.heading)}</h2>
    ${body || "<p>No content available for this section.</p>"}
  </div>`;
}

html += `</div>`;

return [{ json: { emailHtml: html } }];
